    int total_errors = 0;
    for (size_t i = 0; i < all_files.size(); i++) {
        if (!opts.quiet) {
            std::cout << "Checking " << all_files[i] << "...\n";
            if (all_files.size() > 1) {
                int percent = (i + 1) * 100 / all_files.size();
                std::cout << i + 1 << "/" << all_files.size() << " files checked " 
