std::vector<ErrorReport> CodeAnalyzer::analyzeFile(const std::string& filename) {
    std::vector<ErrorReport> errors;

    try {
        std::ifstream file(filename);
        if (!file.is_open()) {
            return errors;
        }

        std::string content((std::istreambuf_iterator<char>(file)),
                           std::istreambuf_iterator<char>());

        // Run different analyzers
        auto array_errors = analyzeArrayBounds(filename, content);
        errors.insert(errors.end(), array_errors.begin(), array_errors.end());

        auto memory_errors = analyzeMemoryIssues(filename, content);
        errors.insert(errors.end(), memory_errors.begin(), memory_errors.end());

        auto logic_errors = analyzeLogicErrors(filename, content);
        errors.insert(errors.end(), logic_errors.begin(), logic_errors.end());

    } catch (...) {
        // Ignore parsing errors
    }

    return errors;
}

std::vector<ErrorReport> CodeAnalyzer::analyzeArrayBounds(const std::string& filename, const std::string& content) {
    std::vector<ErrorReport> errors;

    // Parse the content to find array declarations and accesses
    std::istringstream stream(content);
    std::string line;
    int line_num = 0;

    std::map<std::string, int> array_sizes;  // array name -> size

    while (std::getline(stream, line)) {
        line_num++;

        // Find array declarations: type name[size];
        // Match patterns like: char a[10];, int arr[16];
        std::regex decl_regex(R"(\b(?:char|int|float|double|long|short|unsigned|signed)\s+(\w+)\s*\[\s*(\d+)\s*\]\s*[;=])");
        std::smatch decl_match;

        if (std::regex_search(line, decl_match, decl_regex)) {
            std::string array_name = decl_match[1].str();
            int size = std::stoi(decl_match[2].str());
            array_sizes[array_name] = size;
        }

        // Find array accesses: a[10]
        std::regex access_regex(R"(\b(\w+)\s*\[\s*(\d+)\s*\])");
        std::smatch access_match;
        std::string::const_iterator search_start(line.cbegin());

        while (std::regex_search(search_start, line.cend(), access_match, access_regex)) {
            std::string array_name = access_match[1].str();
            int access_index = std::stoi(access_match[2].str());

            auto it = array_sizes.find(array_name);
            if (it != array_sizes.end()) {
                int size = it->second;
                if (access_index >= size) {
                    ErrorReport error;
                    error.file = filename;
                    error.line = line_num;
                    error.column = std::distance(line.cbegin(), access_match[0].first) + 1;
                    error.severity = "error";
                    error.id = "arrayIndexOutOfBounds";
                    error.cwe = "788";
                    error.message = "Array '" + array_name + "[" + std::to_string(size) + 
                                  "]' index " + std::to_string(access_index) + 
                                  " out of bounds";
                    errors.push_back(error);
                }
            }

            search_start = access_match[0].second;
        }
    }

    return errors;
}

