              << "        <error id=\"autoVariables\" severity=\"error\" msg=\"Address of local auto-variable assigned to a function parameter.\" verbose=\"Dangerous assignment - the function parameter is assigned the address of a local auto-variable. Local auto-variables are reserved from the stack which is freed when the function ends. So the pointer to a local variable is invalid after the function ends.\" cwe=\"562\"/>\n"
              << "        <error id=\"returnReference\" severity=\"error\" msg=\"Reference to local variable returned.\" verbose=\"Reference to local variable returned.\" cwe=\"562\"/>\n"
              << "        <error id=\"danglingReference\" severity=\"error\" msg=\"Non-local reference variable 'x' to local variable 'y'\" verbose=\"Non-local reference variable 'x' to local variable 'y'\" cwe=\"562\"/>\n"
              << "    </errors>\n"
              << "</results>\n";
}

std::vector<std::string> getFilesFromDirectory(const std::string& dir) {
    std::vector<std::string> result;
    const std::vector<std::string> extensions = {
        ".cpp", ".cxx", ".cc", ".c++", ".c", 
        ".ipp", ".ixx", ".tpp", ".txx"
    };

    try {
        for (const auto& entry : fs::recursive_directory_iterator(dir)) {
            if (entry.is_regular_file()) {
                std::string ext = entry.path().extension().string();
                // Convert to lowercase for comparison
                std::transform(ext.begin(), ext.end(), ext.begin(), ::tolower);
                if (std::find(extensions.begin(), extensions.end(), ext) != extensions.end()) {
                    result.push_back(entry.path().string());
                }
            }
        }
    } catch (...) {
        // Ignore errors
    }

    return result;
}

int main(int argc, char* argv[]) {
    Options opts = parseArguments(argc, argv);

    if (opts.show_help) {
        printHelp();
        return 0;
    }

    if (opts.show_version) {
        printVersion();
        return 0;
    }

    if (opts.show_errorlist) {
        printErrorList();
        return 0;
    }

    // If no files provided and not doing special operations
    if (opts.files.empty() && !opts.show_help && !opts.show_version && 
        !opts.show_errorlist && !opts.check_config) {
        std::cout << PROGRAM_NAME << " - A tool for static C/C++ code analysis\n\n"
                  << "Syntax:\n"
                  << "    cppcheck [OPTIONS] [files or paths]\n\n"
                  << "If a directory is given instead of a filename, *.cpp, *.cxx, *.cc, *.c++, *.c, *.ipp,\n"
                  << "*.ixx, *.tpp, and *.txx files are checked recursively from the given directory.\n\n"
                  << "Options:\n"
                  << "    -h, --help               Print this help.\n"
                  << "    --version                Print version.\n";
        return 1;
    }

    // Collect all files to analyze
    std::vector<std::string> all_files;
    for (const auto& file_arg : opts.files) {
        if (fs::is_regular_file(file_arg)) {
            all_files.push_back(file_arg);
        } else if (fs::is_directory(file_arg)) {
            auto dir_files = getFilesFromDirectory(file_arg);
            all_files.insert(all_files.end(), dir_files.begin(), dir_files.end());
        }
    }

    // Analyze files
    int total_errors = 0;
    std::vector<ErrorReport> all_errors;

    for (size_t i = 0; i < all_files.size(); i++) {
        if (!opts.quiet) {
            std::cout << "Checking " << all_files[i] << "...\n";
            if (all_files.size() > 1) {
                int percent = (i + 1) * 100 / all_files.size();
                std::cout << i + 1 << "/" << all_files.size() << " files checked " 
                          << percent << "% done\n";
            }
        }

        auto errors = CodeAnalyzer::analyzeFile(all_files[i]);
        all_errors.insert(all_errors.end(), errors.begin(), errors.end());
        total_errors += errors.size();
    }

    // Output results
    for (const auto& error : all_errors) {
        if (opts.xml_output) {
            std::cout << "<error file=\"" << error.file << "\" line=\"" << error.line 
                      << "\" column=\"" << error.column << "\" severity=\"" << error.severity 
                      << "\" id=\"" << error.id << "\" msg=\"" << error.message;
            if (!error.cwe.empty()) {
                std::cout << "\" cwe=\"" << error.cwe;
            }
            std::cout << "\"/>\n";
        } else {
            if (opts.template_format.empty()) {
                std::cout << "[" << error.file << ":" << error.line << "]: (" 
                          << error.severity << ") " << error.message << " [" 
                          << error.id << "]\n";
            } else {
                // Apply template formatting
                std::string output = opts.template_format;
                size_t pos;
                // Replace {file}
                while ((pos = output.find("{file}")) != std::string::npos) {
                    output.replace(pos, 6, error.file);
                }
                // Replace {line}
                while ((pos = output.find("{line}")) != std::string::npos) {
                    output.replace(pos, 6, std::to_string(error.line));
                }
                // Replace {column}
                while ((pos = output.find("{column}")) != std::string::npos) {
                    output.replace(pos, 8, std::to_string(error.column));
                }
                // Replace {severity}
                while ((pos = output.find("{severity}")) != std::string::npos) {
                    output.replace(pos, 10, error.severity);
                }
                // Replace {message}
                while ((pos = output.find("{message}")) != std::string::npos) {
                    output.replace(pos, 9, error.message);
