                          << error.id << "]\n";
            } else {
                // Apply template formatting
                std::string output = opts.template_format;
                size_t pos;
                // Replace {file}
                while ((pos = output.find("{file}")) != std::string::npos) {
                    output.replace(pos, 6, error.file);
                }
                // Replace {line}
                while ((pos = output.find("{line}")) != std::string::npos) {
                    output.replace(pos, 6, std::to_string(error.line));
                }
                // Replace {column}
                while ((pos = output.find("{column}")) != std::string::npos) {
                    output.replace(pos, 8, std::to_string(error.column));
                }
                // Replace {severity}
                while ((pos = output.find("{severity}")) != std::string::npos) {
                    output.replace(pos, 10, error.severity);
                }
                // Replace {message}
                while ((pos = output.find("{message}")) != std::string::npos) {
                    output.replace(pos, 9, error.message);
                }
                // Replace {id}
                while ((pos = output.find("{id}")) != std::string::npos) {
                    output.replace(pos, 4, error.id);
                }
                std::cout << output << "\n";
            }
        }
    }

    // Return appropriate exit code
    if (error_count > 0 && opts.error_exitcode != 0) {
        exit(opts.error_exitcode);
    }

    return 0;
