        } else if (arg == "--force" || arg == "-f") {
            opts.force = true;
        } else if (arg == "--check-config") {
            opts.check_config = true;
        } else if (arg == "-E") {
            opts.preprocess_only = true;
        } else if (arg.substr(0, 11) == "--template=") {
            opts.template_format = arg.substr(11);
        } else if (arg.substr(0, 17) == "--error-exitcode=") {
            opts.error_exitcode = std::stoi(arg.substr(17));
        } else if (arg.substr(0, 6) == "--std=") {
            opts.std_version = arg.substr(6);
        } else if (arg.substr(0, 9) == "--enable=") {
            opts.enable_checks.push_back(arg.substr(9));
        } else if (arg.substr(0, 10) == "--disable=") {
            opts.disable_checks.push_back(arg.substr(10));
        } else if (arg.substr(0, 2) == "-D" && arg.length() > 2) {
            std::string def = arg.substr(2);
            size_t eq_pos = def.find('=');
            if (eq_pos != std::string::npos) {
                opts.defines[def.substr(0, eq_pos)] = def.substr(eq_pos + 1);
            } else {
                opts.defines[def] = "1";
            }
        } else if (arg.substr(0, 2) == "-U" && arg.length() > 2) {
            opts.undefines.insert(arg.substr(2));
        } else if (arg.substr(0, 2) == "-I" && arg.length() > 2) {
            opts.include_dirs.push_back(arg.substr(2));
        } else if (arg.substr(0, 2) == "-I" && i + 1 < argc) {
            opts.include_dirs.push_back(argv[++i]);
