    if (opts.show_version) {
        printVersion();
        return 0;
    }

    if (opts.show_errorlist) {
        printErrorList();
        return 0;
    }

    // If no files provided and not doing special operations
    if (opts.files.empty() && !opts.show_help && !opts.show_version && 
        !opts.show_errorlist && !opts.check_config) {
