    std::vector<std::string> all_files;
    for (const auto& file_arg : opts.files) {
        if (fs::is_regular_file(file_arg)) {
            all_files.push_back(file_arg);
        } else if (fs::is_directory(file_arg)) {
            auto dir_files = getFilesFromDirectory(file_arg);
            all_files.insert(all_files.end(), dir_files.begin(), dir_files.end());
        }
    }

    // Analyze files
    int error_count = 0;
    std::vector<ErrorReport> all_errors;

    for (size_t i = 0; i < all_files.size(); i++) {
        if (!opts.quiet) {
            std::cout << "Checking " << all_files[i] << "...\n";
            if (all_files.size() > 1) {
                int percent = (i + 1) * 100 / all_files.size();
